// FindFollower retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindFollower(ctx context.Context, exec boil.ContextExecutor, userID int64, followerID int64, selectCols ...string) (*Follower, error) {
	followerObj := &Follower{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"followers\" where \"user_id\"=$1 AND \"follower_id\"=$2", sel,
	)

	q := queries.Raw(query, userID, followerID)

	err := q.Bind(ctx, exec, followerObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "boiler_models: unable to select from followers")
	}

	if err = followerObj.doAfterSelectHooks(ctx, exec); err != nil {
		return followerObj, err
	}

	return followerObj, nil
}

